def step(size: float, /) -> Dict[str, Any]:
    """Cells of one width, aligned to multiples of it: a value is in the cell that starts at the largest multiple of the width at or below it. Every value has a cell, whatever the domain.

    Args:
        size: The width of each cell, in data units.
    """
    if not (isinstance(size, (int, float)) and not isinstance(size, bool)):
        raise TypeError(f"Bin.step(size) must be a finite number > 0, got {type(size).__name__}")
    if not math.isfinite(size):
        raise ValueError(f"Bin.step(size) must be finite, got {size!r}")
    if size <= 0:
        raise ValueError(f"Bin.step(size) must be > 0, got {size!r}")
    out: Dict[str, Any] = {"kind": "step"}
    for _k, _v in [
        ("size", size),
    ]:
        if _v is not None:
            out[_k] = _v
    return out


def thresholds(thresholds: int | list, /) -> Dict[str, Any]:
    """Cells fitted to the domain of the field in the chart's data, which they cover with both ends included: a value on the last edge falls in the last cell, as in numpy's `histogram` and d3's `bin`.

    Args:
        thresholds: A count: about that many cells, with the width a numeric axis with that many ticks would use, so the edges are round numbers. Or a list of edges: the cells end and start at them, with the domain's ends as the outer edges, and an edge outside the domain cuts nothing.
    """
    if isinstance(thresholds, int) and not isinstance(thresholds, bool):
        if thresholds < 1:
            raise ValueError(f"Bin.thresholds(thresholds) must be >= 1, got {thresholds!r}")
    elif isinstance(thresholds, list):
        if len(thresholds) < 1:
            raise ValueError(f"Bin.thresholds(thresholds) must have at least 1 item, got {thresholds!r}")
        for thresholds_item in thresholds:
            if not (isinstance(thresholds_item, (int, float)) and not isinstance(thresholds_item, bool)):
                raise TypeError(f"Bin.thresholds(thresholds) item must be a finite number, got {type(thresholds_item).__name__}")
            if not math.isfinite(thresholds_item):
                raise ValueError(f"Bin.thresholds(thresholds) item must be finite, got {thresholds_item!r}")
    else:
        raise TypeError(f"Bin.thresholds(thresholds) must be a whole number >= 1 or a list of at least 1 item, each item a finite number, got {type(thresholds).__name__}")
    out: Dict[str, Any] = {"kind": "thresholds"}
    for _k, _v in [
        ("thresholds", thresholds),
    ]:
        if _v is not None:
            out[_k] = _v
    return out


def quantiles(quantiles: int | list, /) -> Dict[str, Any]:
    """Cells whose inner edges are quantiles of the field's values in the chart's data (type 7, the default of numpy and d3), with the domain's ends as the outer edges, as in polars' and pandas' `qcut`. Two edges at one value, as many equal values can give, are an error: ask for fewer cells.

    Args:
        quantiles: A count: that many cells, each holding about the same number of values. Or a list of probabilities, each above 0 and below 1: the inner edges are the quantiles at them.
    """
    if isinstance(quantiles, int) and not isinstance(quantiles, bool):
        if quantiles < 1:
            raise ValueError(f"Bin.quantiles(quantiles) must be >= 1, got {quantiles!r}")
    elif isinstance(quantiles, list):
        if len(quantiles) < 1:
            raise ValueError(f"Bin.quantiles(quantiles) must have at least 1 item, got {quantiles!r}")
        for quantiles_item in quantiles:
            if not (isinstance(quantiles_item, (int, float)) and not isinstance(quantiles_item, bool)):
                raise TypeError(f"Bin.quantiles(quantiles) item must be a number > 0 and < 1, got {type(quantiles_item).__name__}")
            if math.isnan(quantiles_item):
                raise ValueError(f"Bin.quantiles(quantiles) item must not be NaN, got {quantiles_item!r}")
            if quantiles_item <= 0:
                raise ValueError(f"Bin.quantiles(quantiles) item must be > 0, got {quantiles_item!r}")
            if quantiles_item >= 1:
                raise ValueError(f"Bin.quantiles(quantiles) item must be < 1, got {quantiles_item!r}")
    else:
        raise TypeError(f"Bin.quantiles(quantiles) must be a whole number >= 1 or a list of at least 1 item, each item a number > 0 and < 1, got {type(quantiles).__name__}")
    out: Dict[str, Any] = {"kind": "quantiles"}
    for _k, _v in [
        ("quantiles", quantiles),
    ]:
        if _v is not None:
            out[_k] = _v
    return out


def hex(*, radius: float | dict) -> Dict[str, Any]:
    """A grid of hexagons with a corner at the top (pointy-top, as in d3-hexbin, ggplot2's `geom_hex` and Observable Plot), with one hexagon centered on the origin (0, 0). The grid covers the domain of the two fields in the chart's data, and every hexagon in it is a cell, empty ones included.

    Args:
        radius: The distance from a hexagon's center to its corners, in data units. A number when both fields share a unit (longitude and latitude), or `{ x, y }`, one per field, when they do not (as in ggplot2's `binwidth = c(x, y)`).
    """
    if isinstance(radius, (int, float)) and not isinstance(radius, bool):
        if not math.isfinite(radius):
            raise ValueError(f"Bin.hex(radius=...) must be finite, got {radius!r}")
