def voronoi(*, seeds: Any) -> Dict[str, Any]:
    """One cell per seed: the points nearer to that seed than to any other (a Voronoi diagram). Each row goes to its nearest seed. The cells are clipped to the box that holds the data and the seeds.

    Args:
        seeds: The seed rows, with the same two fields as the key, such as weather stations for rain gauge readings. Pass the chart's own data to give each row its own cell.
    """
